targets.expr:
holt_winters(
  sum by(uri)(
    rate(
      http_server_requests_seconds_count{
        job="$application",
        pod=~"$instance",
        namespace="$env",
        uri="$http_route",
        uri!~".*/actuator/.*"
      }[30m]
    )
  )[12h:],
  0.5,
  0.5
)

predict_linear(
  sum by(uri)(
    rate(
      http_server_requests_seconds_count{
        job="$application",
        pod=~"$instance",
        namespace="$env",
        uri="$http_route",
        uri!~".*/actuator/.*"
      }[30m]
    )
  )[2h:], 1800
)
